-- Fixes the Starlinen bulk import (rrs_products_import (4).csv, imported
-- 2026-10-08): the source CSV had already lost its original characters to
-- lossy encoding before it reached this site -- every × (multiplication
-- sign), — (em dash) and ’ (apostrophe) in the file had been replaced with
-- the Unicode replacement character (U+FFFD), which is unrecoverable from
-- the file itself. Verified against the surrounding text (always between
-- two numbers for ×, always before a color/pattern word for —, always
-- word+s for ’) and restored below for every affected row's name,
-- description, overview and feature1-4.
--
-- Also backfills product_family/variant_label/product_tier so genuine
-- same-product size/weight/pattern/color variants (sheets and pillowcases
-- by size within a thread count, the two Optima washcloth weights, the
-- two T250 duvet cover patterns per size, and two Classic color pairs)
-- group into one catalog card each, instead of each size/color showing as
-- its own separate card. Towels, bar mops, napkins, aprons and pot
-- holders are deliberately left ungrouped: a washcloth and a bath towel
-- are different products, not size variants of one product, matching how
-- the rest of the catalog already treats towels.
--
-- DATA DEFECT flagged inline below: the two 'Classic 100% Cotton Kitchen
-- Towel' color rows (Hunter Green/White, Light Blue/White) shared the
-- exact same SKU (21068YH091) in the source CSV. Since the bulk importer
-- upserts onConflict:'sku' in file order, Light Blue/White (listed second
-- in the file) silently overwrote Hunter Green/White on import -- Hunter
-- Green never existed as its own row afterward. This migration re-inserts
-- it under a PLACEHOLDER SKU (21068YH091-HG) so both colors exist as a
-- real family; Eric should get Starlinen's actual second SKU for this
-- item and swap the placeholder out once he has it.
--
-- T300 added to product_tier's closed vocabulary (Millennium T300 sheets
-- appear in this CSV; only 180/200/250 were previously allowed alongside
-- the quality-tier words -- same gap 20260930b_thread_count_tier.sql
-- closed for 180/200/250 themselves).

alter table public.products
  drop constraint if exists products_product_tier_check;
alter table public.products
  add constraint products_product_tier_check check (
    product_tier is null or product_tier in
      ('Economy','Premium','Luxury','Ultra Luxury','Suites','Ringspun',
       'Hospitality','Wrinkle-Free','180','200','250','300')
  );

begin;

update public.products set name = 'Bulk Case Pack of 12 Economy Cotton Washcloths, 12 × 12 in. — White', description = 'Complete your guest bathroom essentials with this Economy white cotton washcloth. Measuring 12 × 12 inches, it provides a compact cloth for face and body washing in hotels, motels, and vacation rentals. Pair it with Economy hand towels and bath towels to create a coordinated white towel collection. Sold by the dozen, with 12 pieces per selling unit and the listed cost applying to one dozen.', overview = 'Product Size: 12 × 12 in. | Product Type: Wash Cloth | Collection: Economy | Material: Cotton | Color: White', feature1 = 'Economy cotton washcloth for guest bathrooms', feature2 = '12 × 12 in. washcloth for face and body washing', feature3 = 'Compact bathroom essential for hotels and vacation rentals', feature4 = 'White washcloth coordinates with matching hand and bath towels', product_family = NULL, variant_label = NULL, product_tier = 'Economy', updated_at = now() where sku = '11012WH400';
